/* Studio voice index and coverage (openspec better-voice, tasks 4.2 and 3.2). js/voice-index.js is generated by
   tools/voice/record.mjs and publish.mjs; tools/voice/manifest.json lists every recorded whole line (by hash) and
   clip. Every Explorer line must be recorded whole or fully covered by clips, and overall coverage stays at or above
   99%, so a wording change cannot quietly fall back to the device voice. Before the first recording there is no
   manifest and the coverage checks are skipped. */
import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { STUDIO } from '../js/voice-index.js';
import { lineHash, planLine } from '../js/voice-plan.js';
import { normalize } from '../js/voice.js';
import { SKILLS } from '../js/skills/index.js';
import { seeded, kata, KATAS_PER_TRICK } from '../js/levels.js';
import { TRICKS } from '../js/vedic.js';
import { makeSet } from '../js/arena.js';
import { wholeSkills, fixedLines, STITCHED_K2 } from '../tools/voice/lines.mjs';
import { allExplanationLines } from '../js/explain-lines.js';
import { VIDEOS, LINKS } from '../js/videos.js';

const MANIFEST = new URL('../tools/voice/manifest.json', import.meta.url);
const manifest = existsSync(MANIFEST) ? JSON.parse(readFileSync(MANIFEST, 'utf8')) : null;
const spoken = p => [p.say || p.q, ...(p.hints || [])].filter(Boolean);

test('the index: Aoede, served from /vedic-math/voice/, and an archive only with its hash and files', () => {
  assert.equal(STUDIO.voice, 'en-US-Chirp3-HD-Aoede');
  assert.equal(STUDIO.base, '/vedic-math/voice/');
  assert.equal(!!STUDIO.tag, !!STUDIO.sha256, 'a tag and its sha256 come together');
  /* record.mjs writes the manifest with the tag cleared; only publish.mjs sets it, so a manifest without a tag is a
     recording that was never published (the site would ask for files no release holds) */
  if (manifest) assert.ok(STUDIO.tag && STUDIO.sha256, 'tools/voice/manifest.json exists: run tools/voice/publish.mjs so js/voice-index.js names its archive');
  if (STUDIO.tag || manifest) {
    assert.match(STUDIO.tag, /^voice-[0-9a-f]{10}$/);
    assert.match(STUDIO.sha256, /^[0-9a-f]{64}$/);
    assert.match(STUDIO.lineSet, /^l\/set\.[0-9a-f]{10}\.bin$/);
    assert.match(STUDIO.dir, /^p\/dir\.[0-9a-f]{10}\.json$/);
    assert.ok(STUDIO.packs.some(p => p.name === 'core'), 'a core pack');
    for (const p of STUDIO.packs) { assert.match(p.audio, /^p\/[\w-]+\.[0-9a-f]{10}\.m4a$/); assert.match(p.map, /^p\/[\w-]+\.[0-9a-f]{10}\.json$/); }
    assert.ok(manifest, 'a published archive has its manifest in tools/voice/manifest.json');
  }
});

test('the index stays small: it never lists line hashes (they live in the archive and the repo-only manifest)', () => {
  const size = readFileSync(new URL('../js/voice-index.js', import.meta.url)).length;
  assert.ok(size < 8000, `js/voice-index.js is ${size} bytes`);
});

test('whole lines cover every K to 2 Skill except three-digit adding and comparing', () => {
  const ids = wholeSkills().map(s => s.id);
  for (const s of SKILLS.filter(s => ['K', '1', '2'].includes(String(s.grade)))) assert.equal(ids.includes(s.id), !STITCHED_K2.includes(s.id), s.id);
  if (STUDIO.tag) assert.deepEqual(STUDIO.coveredSkills, ids);
});

const covered = (words, lines, clips) => lines.has(lineHash(manifest.voice, words)) || planLine(words).every(p => !p.clip || clips.has(p.clip));

test('every Explorer line has studio audio', { skip: !manifest && 'nothing recorded yet (no tools/voice/manifest.json)' }, () => {
  const lines = new Set(manifest.lines), clips = new Set(manifest.clips), miss = new Set();
  const check = t => { const w = normalize(t); if (w && !covered(w, lines, clips)) miss.add(w); };
  fixedLines().forEach(check);
  seeded('voice-coverage-explorer', () => {
    for (const s of SKILLS.filter(s => ['K', '1', '2'].includes(String(s.grade)))) for (const lv of [1, 2, 3]) for (let i = 0; i < 300; i++) { let p; try { p = s.gen(lv); } catch (e) { continue; } spoken(p).forEach(check); }
  });
  for (let d = 0; d < 20; d++) makeSet('explorer', 'voice-coverage-' + d).forEach(p => spoken(p).forEach(check));
  assert.deepEqual([...miss].slice(0, 10), [], `${miss.size} Explorer lines have no studio audio; re-run tools/voice/lines.mjs, record.mjs and publish.mjs`);
});

test('studio audio covers at least 99% of all lines', { skip: !manifest && 'nothing recorded yet (no tools/voice/manifest.json)' }, () => {
  const lines = new Set(manifest.lines), clips = new Set(manifest.clips); let all = 0, ok = 0;
  const check = t => { const w = normalize(t); if (!w) return; all++; if (covered(w, lines, clips)) ok++; };
  seeded('voice-coverage-all', () => {
    for (const s of SKILLS) for (const lv of [1, 2, 3]) for (let i = 0; i < 100; i++) { let p; try { p = s.gen(lv); } catch (e) { continue; } spoken(p).forEach(check); }
  });
  for (const t of TRICKS) for (let n = 1; n <= KATAS_PER_TRICK; n += 5) kata(t.id, n).problems.forEach(p => spoken(p).forEach(check));
  for (const league of ['challenger', 'pro']) for (let d = 0; d < 5; d++) makeSet(league, 'voice-coverage-' + d).forEach(p => spoken(p).forEach(check));
  assert.ok(ok / all >= 0.99, `coverage ${(ok / all * 100).toFixed(2)}% of ${all} lines`);
});

/* Explanations are recorded whole only (never stitched from clips), so a Listen line whose hash is not in the manifest
   falls back to the device voice. A todo until the re-record of explanation-audio task 4.6 (the wording has moved on
   since the 2026-10-17 recording); that task removes the todo so the check becomes a hard gate. */
test('every explanation line is recorded whole', { skip: !manifest && 'nothing recorded yet (no tools/voice/manifest.json)', todo: 'until the explanation-audio 4.6 re-record' }, () => {
  const lines = new Set(manifest.lines), miss = [];
  for (const { text, src } of allExplanationLines({ videos: VIDEOS, links: LINKS })) { const w = normalize(text); if (w && !lines.has(lineHash(manifest.voice, w))) miss.push(`${src}: ${w}`); }
  assert.deepEqual(miss.slice(0, 10), [], `${miss.length} explanation lines have no whole recording; re-run tools/voice/lines.mjs, record.mjs and publish.mjs`);
});
